	/** Every part of {@link #whale()} by name. */
	public static Map<String, ModelPart> whaleParts(ModelPart root) {
		Map<String, ModelPart> m = new HashMap<>();
		m.put("body", root.getChild("body"));
		m.put("head", root.getChild("body").getChild("head"));
		m.put("jaw", root.getChild("body").getChild("head").getChild("jaw"));
		m.put("eyeR", root.getChild("body").getChild("head").getChild("eyeR"));
		m.put("lidR", root.getChild("body").getChild("head").getChild("lidR"));
		m.put("flipperR", root.getChild("body").getChild("flipperR"));
		m.put("flipperTipR", root.getChild("body").getChild("flipperR").getChild("flipperTipR"));
		m.put("eyeL", root.getChild("body").getChild("head").getChild("eyeL"));
		m.put("lidL", root.getChild("body").getChild("head").getChild("lidL"));
		m.put("flipperL", root.getChild("body").getChild("flipperL"));
		m.put("flipperTipL", root.getChild("body").getChild("flipperL").getChild("flipperTipL"));
		m.put("tail1", root.getChild("body").getChild("tail1"));
		m.put("tail2", root.getChild("body").getChild("tail1").getChild("tail2"));
		m.put("tail3", root.getChild("body").getChild("tail1").getChild("tail2").getChild("tail3"));
		m.put("fluke", root.getChild("body").getChild("tail1").getChild("tail2").getChild("tail3").getChild("fluke"));
		m.put("spray", root.getChild("spray"));
		return m;
	}

